// spec: AC #e824b3d3
// seed: tests/seed.user.spec.ts
import path from 'node:path';
import { test, expect } from '@playwright/test';
import { startMonitoring, endMonitoring } from '../helpers/monitor';

test.use({ storageState: path.join(__dirname, '../../../auth/user.json') });
test.setTimeout(120_000);

test.describe('Экстренные действия', () => {
  test('Действия в окне тревоги, отмена звонка 101 и ссылка МДА #e824b3d3 @iphone @data', async ({ page }) => {
    const telNavigations: string[] = [];
    page.on('request', (req) => { if (req.url().startsWith('tel:')) telNavigations.push(req.url()); });
    page.on('framenavigated', (frame) => { if (frame.url().startsWith('tel:')) telNavigations.push(frame.url()); });

    await startMonitoring(page, 'headUnder');

    // Ожидание тревоги
    await expect(page.getByText('זוהתה סכנה בבריכה').first()).toBeVisible({ timeout: 45_000 });

    // Проверка кнопок
    const call = page.getByRole('button', { name: 'חיוג למד״א 101' }).filter({ visible: true });
    const mda = page.getByRole('button', { name: 'לאתר ולאפליקציה של מד״א' }).filter({ visible: true });
    await expect(call).toBeVisible();
    await expect(page.getByRole('button', { name: 'עזרה ראשונה והחייאה' }).filter({ visible: true })).toBeVisible();
    await expect(mda).toBeVisible();
    await expect(page.getByRole('button', { name: 'זו אזעקת שווא' }).filter({ visible: true })).toBeVisible();

    const callBox = (await call.boundingBox())!;
    const mdaBox = (await mda.boundingBox())!;
    expect(mdaBox.height).toBeLessThan(callBox.height);

    // Диалог 101 и отмена (кнопку подтверждения не нажимаем)
    await call.click();
    await expect(page.getByText('לחייג למד״א 101?')).toBeVisible();
    await page.getByRole('button', { name: 'ביטול' }).filter({ visible: true }).click();
    await expect(page.getByText('לחייג למד״א 101?')).toBeHidden();
    await expect(page.getByText('זוהתה סכנה בבריכה').first()).toBeVisible();

    // Ссылка МДА
    const [popup] = await Promise.all([
      page.context().waitForEvent('page'),
      mda.click(),
    ]);
    await expect.poll(() => popup.url(), { timeout: 15_000 }).toContain('mdais.org');
    await popup.close();

    await endMonitoring(page);
    expect(telNavigations).toEqual([]);
  });
});
